//! Differential test: replays every `transformForWrite` call captured from the
//! TS implementation (test/__rs/write/fixtures, generated by
//! test/__rs/write/capture.int.spec.ts and the capture setup for upstream
//! suites) and asserts the Rust output, the mutated input data and errors are
//! identical. Fixtures are gzip-compressed JSON (`*.json.gz`, read with `gzip -dc`).

use std::path::PathBuf;

use indexmap::IndexMap;
use payload_engine::js::{JsVal, decode_graph_typed};
use payload_sql_write::{StaticWriteAdapter, TransformForWriteArgs, encode_value, transform_for_write};
use serde_json::{Value as Json, json};

fn fixtures_dir() -> PathBuf {
  PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../test/__rs/write/fixtures")
}

fn decode(v: &Json) -> JsVal {
  decode_graph_typed(&json!({ "objects": [], "root": v })).expect("decodable fixture value")
}

/// Ordered deep equality (key order matters, numbers compare by value).
fn first_diff(a: &Json, b: &Json, path: &str) -> Option<String> {
  match (a, b) {
    (Json::Number(x), Json::Number(y)) => {
      (x.as_f64() != y.as_f64()).then(|| format!("{path}: {x} != {y}"))
    }
    (Json::Object(x), Json::Object(y)) => {
      let xk: Vec<_> = x.keys().collect();
      let yk: Vec<_> = y.keys().collect();
      if xk != yk {
        return Some(format!("{path}: keys {xk:?} != {yk:?}"));
      }
      x.iter().zip(y.iter()).find_map(|((k, xv), (_, yv))| first_diff(xv, yv, &format!("{path}.{k}")))
    }
    (Json::Array(x), Json::Array(y)) => {
      if x.len() != y.len() {
        return Some(format!("{path}: len {} != {}", x.len(), y.len()));
      }
      x.iter().zip(y.iter()).enumerate().find_map(|(i, (xv, yv))| first_diff(xv, yv, &format!("{path}[{i}]")))
    }
    _ => (a != b).then(|| format!("{path}: {a} != {b}")),
  }
}

#[test]
fn replay_captured_transform_for_write_calls() {
  let dir = fixtures_dir();
  let filter = std::env::var("RS_WRITE_FIXTURE").ok();
  let mut files: Vec<_> = std::fs::read_dir(&dir)
    .unwrap_or_else(|e| panic!("missing fixtures dir {}: {e}", dir.display()))
    .filter_map(|e| e.ok().map(|e| e.path()))
    .filter(|p| p.to_string_lossy().ends_with(".json.gz"))
    .filter(|p| filter.as_ref().is_none_or(|f| p.to_string_lossy().contains(f.as_str())))
    .collect();
  files.sort();
  assert!(!files.is_empty(), "no fixtures in {} (see test/__rs/write/runCapture.ts)", dir.display());

  let mut total = 0usize;
  let mut errors_expected = 0usize;
  let mut failures: Vec<String> = Vec::new();

  for file in &files {
    let out = std::process::Command::new("gzip").arg("-dc").arg(file).output().expect("gzip available");
    assert!(out.status.success(), "gzip -dc {} failed", file.display());
    let text = String::from_utf8(out.stdout).expect("utf8 fixture");
    let fixture: Json = serde_json::from_str(&text).expect("valid fixture json");
    let name = file.file_name().unwrap_or_default().to_string_lossy().to_string();
    let mut file_total = 0usize;
    let mut file_failures = 0usize;

    for (group_index, group) in fixture["groups"].as_array().into_iter().flatten().enumerate() {
      let a = &group["adapter"];
      let mut adapter = StaticWriteAdapter {
        name: a["name"].as_str().unwrap_or_default().to_string(),
        blocks_as_json: a["blocksAsJSON"].as_bool().unwrap_or(false),
        table_name_map: a["tableNameMap"]
          .as_object()
          .into_iter()
          .flatten()
          .map(|(k, v)| (k.clone(), v.as_str().unwrap_or_default().to_string()))
          .collect(),
        tables: a["tables"]
          .as_object()
          .into_iter()
          .flatten()
          .map(|(k, v)| (k.clone(), v.as_bool().unwrap_or(false)))
          .collect(),
        config_blocks: decode(&a["configBlocks"]),
        block_index_key: Some("__internalBlockTableNameIndex".into()),
      };
      let fields: IndexMap<String, JsVal> =
        group["fields"].as_object().into_iter().flatten().map(|(k, v)| (k.clone(), decode(v))).collect();

      for (call_index, call) in group["calls"].as_array().into_iter().flatten().enumerate() {
        total += 1;
        file_total += 1;
        let id = format!("{name} group {group_index} call {call_index}");
        let fields = &fields[call["fields"].as_str().unwrap_or_default()];
        // `dataGraph` keeps object identity and typed `Date`s / `bigint`s; older fixtures store
        // `data` as a tree with dates as strings.
        let mut data = match call.get("dataGraph") {
          Some(graph) => decode_graph_typed(graph).expect("decodable data graph"),
          None => decode(&call["data"]),
        };
        // The adapter can be reconfigured at runtime (e.g. `payload.db.blocksAsJSON = true`).
        if let Some(v) = call["blocksAsJSON"].as_bool() {
          adapter.blocks_as_json = v;
        }
        if let Some(v) = call["adapterName"].as_str() {
          adapter.name = v.to_string();
        }
        let args = TransformForWriteArgs {
          adapter: &adapter,
          enable_atomic_writes: call["enableAtomicWrites"].as_bool().unwrap_or(false),
          fields,
          parent_is_localized: call["parentIsLocalized"].as_bool().unwrap_or(false),
          path: call["path"].as_str().unwrap_or(""),
          table_name: call["tableName"].as_str().unwrap_or_default(),
          now: call["now"].as_f64(),
        };
        let result = transform_for_write(args, &mut data);

        let mut failure = None;
        match (&result, call.get("error")) {
          (Err(err), Some(expected)) => {
            errors_expected += 1;
            if expected["name"].as_str() != Some(err.name.as_str())
              || expected["message"].as_str() != Some(err.message.as_str())
            {
              failure = Some(format!("error {} != expected {expected}", err));
            }
          }
          (Err(err), None) => failure = Some(format!("unexpected error {err}")),
          (Ok(_), Some(expected)) => failure = Some(format!("expected error {expected}")),
          (Ok(out), None) => {
            if let Some(diff) = first_diff(&out.encode(), &call["output"], "output") {
              failure = Some(diff);
            }
          }
        }
        if failure.is_none()
          && let Some(diff) = first_diff(&encode_value(&data), &call["dataAfter"], "dataAfter")
        {
          failure = Some(diff);
        }
        if let Some(f) = failure {
          file_failures += 1;
          failures.push(format!("{id} (table {}): {f}", call["tableName"]));
        }
      }
    }
    eprintln!("{name}: {}/{file_total} match", file_total - file_failures);
  }

  eprintln!(
    "replayed {total} transformForWrite calls from {} fixture files ({errors_expected} expected errors): {} match, {} differ",
    files.len(),
    total - failures.len(),
    failures.len()
  );
  for f in failures.iter().take(40) {
    eprintln!("  {f}");
  }
  assert!(total > 0, "replayed zero transformForWrite calls");
  assert!(failures.is_empty(), "{} of {total} calls differ", failures.len());
}
